34		ID int32
35	}
36	
37	func (s *Store) CreateIdentityProvider(ctx context.Context, create *storepb.IdentityProvider) (*storepb.IdentityProvider, error) {
38		raw, err := convertIdentityProviderToRaw(create)
39		if err != nil {
40			return nil, err
41		}
42		identityProviderRaw, err := s.driver.CreateIdentityProvider(ctx, raw)
43		if err != nil {
44			return nil, err
45		}
46	
47		identityProvider, err := convertIdentityProviderFromRaw(identityProviderRaw)
48		if err != nil {
49			return nil, err
50		}
51		return identityProvider, nil
52	}
53	
54	func (s *Store) ListIdentityProviders(ctx context.Context, find *FindIdentityProvider) ([]*storepb.IdentityProvider, error) {
55		stored, err := s.listStoredIdentityProviders(ctx, find)
56		if err != nil {
57			return nil, err
58		}
59		// File-backed providers do not have database IDs. ID-filtered reads are raw
60		// stored-resource lookups used by mutation paths.
61		if find.ID != nil {
62			return stored, nil
63		}
64		if find.UID != nil {
65			if provider := s.getDeploymentIdentityProvider(*find.UID); provider != nil {
66				return []*storepb.IdentityProvider{provider}, nil
67			}
68			return stored, nil
69		}
70	
71		deploymentProviders := s.listDeploymentIdentityProviders()
72		deploymentByUID := make(map[string]*storepb.IdentityProvider, len(deploymentProviders))
73		for _, provider := range deploymentProviders {
74			deploymentByUID[provider.Uid] = provider
75		}
76		identityProviders := make([]*storepb.IdentityProvider, 0, len(stored)+len(deploymentProviders))
77		for _, provider := range stored {
78			if configured := deploymentByUID[provider.Uid]; configured != nil {
79				identityProviders = append(identityProviders, configured)
80				delete(deploymentByUID, provider.Uid)
81				continue
82			}
83			identityProviders = append(identityProviders, provider)
84		}
85		// listDeploymentIdentityProviders is UID-sorted, so providers that exist
86		// only in deployment configuration are appended deterministically without
87		// reordering existing database-backed providers.
88		for _, provider := range deploymentProviders {
89			if deploymentByUID[provider.Uid] != nil {
90				identityProviders = append(identityProviders, provider)
91			}
92		}
93		return identityProviders, nil
94	}
95	
96	func (s *Store) listStoredIdentityProviders(ctx context.Context, find *FindIdentityProvider) ([]*storepb.IdentityProvider, error) {
97		list, err := s.driver.ListIdentityProviders(ctx, find)
98		if err != nil {
99			return nil, err
100		}
101	
102		identityProviders := []*storepb.IdentityProvider{}
103		for _, raw := range list {
104			identityProvider, err := convertIdentityProviderFromRaw(raw)
105			if err != nil {
106				return nil, err
107			}
108			identityProviders = append(identityProviders, identityProvider)
109		}
110		return identityProviders, nil
111	}
112	
113	func (s *Store) GetIdentityProvider(ctx context.Context, find *FindIdentityProvider) (*storepb.IdentityProvider, error) {
114		list, err := s.ListIdentityProviders(ctx, find)
115		if err != nil {
116			return nil, err
117		}
118		if len(list) == 0 {
119			return nil, nil
120		}
121		if len(list) > 1 {
122			return nil, errors.New("found multiple identity providers")
123		}
124	
125		identityProvider := list[0]
126		return identityProvider, nil
127	}
128	
129	// GetStoredIdentityProvider returns a database-backed provider without deployment shadowing.
130	func (s *Store) GetStoredIdentityProvider(ctx context.Context, find *FindIdentityProvider) (*storepb.IdentityProvider, error) {
131		list, err := s.listStoredIdentityProviders(ctx, find)
132		if err != nil {
133			return nil, err
134		}
135		if len(list) == 0 {
136			return nil, nil
137		}
138		if len(list) > 1 {
139			return nil, errors.New("found multiple stored identity providers")
140		}
141		return list[0], nil
142	}
143	
144	type UpdateIdentityProviderV1 struct {
145		ID               int32
146		Type             storepb.IdentityProvider_Type
147		Name             *string
148		IdentifierFilter *string
149		Config           *storepb.IdentityProviderConfig
150	}
151	
152	func (s *Store) UpdateIdentityProvider(ctx context.Context, update *UpdateIdentityProviderV1) (*storepb.IdentityProvider, error) {
153		updateRaw := &UpdateIdentityProvider{
154			ID: update.ID,
155		}
156		if update.Name != nil {
157			updateRaw.Name = update.Name
158		}
159		if update.IdentifierFilter != nil {
160			updateRaw.IdentifierFilter = update.IdentifierFilter
161		}
162		if update.Config != nil {
163			configRaw, err := convertIdentityProviderConfigToRaw(update.Type, update.Config)
164			if err != nil {
165				return nil, err
166			}
167			updateRaw.Config = &configRaw
168		}
169		identityProviderRaw, err := s.driver.UpdateIdentityProvider(ctx, updateRaw)
170		if err != nil {
171			return nil, err
172		}
173	
174		identityProvider, err := convertIdentityProviderFromRaw(identityProviderRaw)
175		if err != nil {
176			return nil, err
177		}
178		return identityProvider, nil
179	}
180	
181	func (s *Store) DeleteIdentityProvider(ctx context.Context, delete *DeleteIdentityProvider) error {
182		err := s.driver.DeleteIdentityProvider(ctx, delete)
183		if err != nil {
184			return err
185		}
186		return nil
187	}
188	
189	func convertIdentityProviderFromRaw(raw *IdentityProvider) (*storepb.IdentityProvider, error) {
190		identityProvider := &storepb.IdentityProvider{
191			Id:               raw.ID,
192			Uid:              raw.UID,
193			Name:             raw.Name,
194			Type:             raw.Type,
195			IdentifierFilter: raw.IdentifierFilter,
196		}
197		config, err := convertIdentityProviderConfigFromRaw(identityProvider.Type, raw.Config)
198		if err != nil {
199			return nil, err
200		}
201		identityProvider.Config = config
202		return identityProvider, nil
203	}
204	
205	func convertIdentityProviderToRaw(identityProvider *storepb.IdentityProvider) (*IdentityProvider, error) {
206		raw := &IdentityProvider{
207			ID:               identityProvider.Id,
208			UID:              identityProvider.Uid,
209			Name:             identityProvider.Name,
210			Type:             identityProvider.Type,
211			IdentifierFilter: identityProvider.IdentifierFilter,
212		}
213		configRaw, err := convertIdentityProviderConfigToRaw(identityProvider.Type, identityProvider.Config)
214		if err != nil {
215			return nil, err
216		}
217		raw.Config = configRaw
218		return raw, nil
219	}
220	
221	func convertIdentityProviderConfigFromRaw(identityProviderType storepb.IdentityProvider_Type, raw string) (*storepb.IdentityProviderConfig, error) {
222		config := &storepb.IdentityProviderConfig{}
223		if identityProviderType == storepb.IdentityProvider_OAUTH2 {
224			oauth2Config := &storepb.OAuth2Config{}
225			if err := protojsonUnmarshaler.Unmarshal([]byte(raw), oauth2Config); err != nil {
226				return nil, errors.Wrap(err, "Failed to unmarshal OAuth2Config")
227			}
228			config.Config = &storepb.IdentityProviderConfig_Oauth2Config{Oauth2Config: oauth2Config}
229		}
230		return config, nil
231	}
232	
233	func convertIdentityProviderConfigToRaw(identityProviderType storepb.IdentityProvider_Type, config *storepb.IdentityProviderConfig) (string, error) {
234		raw := ""
235		if identityProviderType == storepb.IdentityProvider_OAUTH2 {
236			bytes, err := protojson.Marshal(config.GetOauth2Config())
237			if err != nil {
238				return "", errors.Wrap(err, "Failed to marshal OAuth2Config")
239			}
240			raw = string(bytes)
241		}
242		return raw, nil
243	}
